mapper.select:
select a.id,a.name,a.ALARM_LEVEL as alarmLevel,a.ALARM_CODE as alarmCode,a.STATUS_FLAG as statusFlag,a.FLAG_TYPE
as flagType,a.EVENT_TYPE_ID as eventTypeId,a.DESC_STR as descStr,a.PLAN_STR as planStr,
a.CREATE_TIME as createTime,a.CREATOR,a.MODIFY_TIME as modifyTime,a.MODIFIER,a.TEMPLATE_STR as templateStr
from ALARM_REPOSITORY a


        and a.name like concat(concat('%',#{query.name}),'%')


        and a.ALARM_LEVEL = #{query.alarmLevel}


        and a.ALARM_CODE = #{query.alarmCode}


        and a.FLAG_TYPE = #{query.flagType}


        and a.EVENT_TYPE_ID = #{query.eventTypeId}




        order by a.${query.orderBy}


        order by a.CREATE_TIME




        ${query.sort}


        desc
